def local_predict(G,S,r,metric='cheb',exclude_bg=None,only_if_unique=True):
 out=G.copy();h,w=G.shape
 for i,j in zip(*np.where(G==S)):
  cs=[]
  for a in range(max(0,i-r),min(h,i+r+1)):
   for b in range(max(0,j-r),min(w,j+r+1)):
    if G[a,b]==S:continue
    d=max(abs(a-i),abs(b-j)) if metric=='cheb' else abs(a-i)+abs(b-j)
    if d<=r and (exclude_bg is None or G[a,b]!=exclude_bg):cs.append(int(G[a,b]))
  co=Counter(cs)
  if co:
   most=co.most_common();
   if len(most)==1 or not only_if_unique or most[0][1]>most[1][1]:out[i,j]=most[0][0]
 return out
